import{_ as e,o as s,c as o,l as n,t as i,N as a}from"./chunks/framework.Bbd9fWQx.js";const k=JSON.parse('{"title":"git-range-diff | x-cmd man (git man1) | Compare two commit ranges (e.g. two versions of a\\nbranch)","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-range-diff - Compare two commit ranges (e.g. two versions of a\\nbranch)","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-range-diff | x-cmd man (git man1) | Compare two commit ranges (e.g. two versions of a\\nbranch)"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-range-diff - Compare two commit ranges (e.g. two versions of a\\nbranch)"}]]},"headers":[],"params":{"isMan":true,"man":"git-range-diff","category":"git man1","desc":"Compare two commit ranges (e.g. two versions of a\\nbranch)"},"relativePath":"git/man1/git-range-diff.md","filePath":"git/man1/git-range-diff.md"}'),r={name:"git/man1/git-range-diff.md"},g={class:"visually-hidden"},h=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-range-diff - Compare two commit ranges (e.g. two versions of a branch)</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> range-diff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--color=[&lt;when&gt;]] [--no-color] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diff-options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[--no-dual-color] [--creation-factor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">factor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[--left-only </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --right-only]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">range1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">range</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rev1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;rev2&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">base</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">1&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rev</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[--] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This command shows the differences between two versions of a patch series, or more generally, two commit ranges (ignoring merge commits).</p><p>In the presence of <strong>&lt;path&gt;</strong> arguments, these commit ranges are limited accordingly.</p><p>To that end, it first finds pairs of commits from both commit ranges that correspond with each other. Two commits are said to correspond when the diff between their patches (i.e. the author information, the commit message and the commit diff) is reasonably small compared to the patches&#39; size. See \`\`Algorithm\`\` below for details.</p><p>Finally, the list of matching commits is shown in the order of the second commit range, with unmatched commits being inserted just after all of their ancestors have been shown.</p><p>There are three ways to specify the commit ranges:</p><blockquote><p>·</p><p><strong>&lt;range1&gt; &lt;range2&gt;</strong>: Either commit range can be of the form <strong>&lt;base&gt;..&lt;rev&gt;</strong>, <strong>&lt;rev&gt;^!</strong> or <strong>&lt;rev&gt;^-&lt;n&gt;</strong>. See <strong>SPECIFYING RANGES</strong> in <strong>gitrevisions</strong>(7) for more details.</p></blockquote><blockquote><p>·</p><p><strong>&lt;rev1&gt;...&lt;rev2&gt;</strong>. This is equivalent to <strong>&lt;rev2&gt;..&lt;rev1&gt; &lt;rev1&gt;..&lt;rev2&gt;</strong>.</p></blockquote><blockquote><p>·</p><p><strong>&lt;base&gt; &lt;rev1&gt; &lt;rev2&gt;</strong>: This is equivalent to <strong>&lt;base&gt;..&lt;rev1&gt; &lt;base&gt;..&lt;rev2&gt;</strong>.</p></blockquote><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--no-dual-color</p><blockquote><p>When the commit diffs differ, <strong>git range-diff</strong> recreates the original diffs&#39; coloring, and adds outer -/+ diff markers with the <strong>background</strong> being red/green to make it easier to see e.g. when there was a change in what exact lines were added.</p><p>Additionally, the commit diff lines that are only present in the first commit range are shown &quot;dimmed&quot; (this can be overridden using the <strong>color.diff.&lt;slot&gt;</strong> config setting where <strong>&lt;slot&gt;</strong> is one of <strong>contextDimmed</strong>, <strong>oldDimmed</strong> and <strong>newDimmed</strong>), and the commit diff lines that are only present in the second commit range are shown in bold (which can be overridden using the config settings <strong>color.diff.&lt;slot&gt;</strong> with <strong>&lt;slot&gt;</strong> being one of <strong>contextBold</strong>, <strong>oldBold</strong> or <strong>newBold</strong>).</p><p>This is known to <strong>range-diff</strong> as &quot;dual coloring&quot;. Use <strong>--no-dual-color</strong> to revert to color all lines according to the outer diff markers (and completely ignore the inner diff when it comes to color).</p></blockquote><p>--creation-factor=&lt;percent&gt;</p><blockquote><p>Set the creation/deletion cost fudge factor to <strong>&lt;percent&gt;</strong>. Defaults to 60. Try a larger value if <strong>git range-diff</strong> erroneously considers a large change a total rewrite (deletion of one commit and addition of another), and a smaller one in the reverse case. See the \`\`Algorithm\`\` section below for an explanation why this is needed.</p></blockquote><p>--left-only</p><blockquote><p>Suppress commits that are missing from the first specified range (or the &quot;left range&quot; when using the <strong>&lt;rev1&gt;...&lt;rev2&gt;</strong> format).</p></blockquote><p>--right-only</p><blockquote><p>Suppress commits that are missing from the second specified range (or the &quot;right range&quot; when using the <strong>&lt;rev1&gt;...&lt;rev2&gt;</strong> format).</p></blockquote><p>--[no-]notes[=&lt;ref&gt;]</p><blockquote><p>This flag is passed to the <strong>git log</strong> program (see <strong>git-log</strong>(1)) that generates the patches.</p></blockquote><p>&lt;range1&gt; &lt;range2&gt;</p><blockquote><p>Compare the commits specified by the two ranges, where <strong>&lt;range1&gt;</strong> is considered an older version of <strong>&lt;range2&gt;</strong>.</p></blockquote><p>&lt;rev1&gt;...&lt;rev2&gt;</p><blockquote><p>Equivalent to passing <strong>&lt;rev2&gt;..&lt;rev1&gt;</strong> and <strong>&lt;rev1&gt;..&lt;rev2&gt;</strong>.</p></blockquote><p>&lt;base&gt; &lt;rev1&gt; &lt;rev2&gt;</p><blockquote><p>Equivalent to passing <strong>&lt;base&gt;..&lt;rev1&gt;</strong> and <strong>&lt;base&gt;..&lt;rev2&gt;</strong>. Note that <strong>&lt;base&gt;</strong> does not need to be the exact branch point of the branches. Example: after rebasing a branch <strong>my-topic</strong>, <strong>git range-diff my-topic@{u} my-topic@{1} my-topic</strong> would show the differences introduced by the rebase.</p></blockquote><p><strong>git range-diff</strong> also accepts the regular diff options (see <strong>git-diff</strong>(1)), most notably the <strong>--color=[&lt;when&gt;]</strong> and <strong>--no-color</strong> options. These options are used when generating the &quot;diff between patches&quot;, i.e. to compare the author, commit message and diff of corresponding old/new commits. There is currently no means to tweak most of the diff options passed to <strong>git log</strong> when generating those patches.</p><h2 id="output-stability" tabindex="-1">OUTPUT STABILITY <a class="header-anchor" href="#output-stability" aria-label="Permalink to &quot;OUTPUT STABILITY&quot;">​</a></h2><p>The output of the <strong>range-diff</strong> command is subject to change. It is intended to be human-readable porcelain output, not something that can be used across versions of Git to get a textually stable <strong>range-diff</strong> (as opposed to something like the <strong>--stable</strong> option to <strong>git-patch-id</strong>(1)). There&#39;s also no equivalent of <strong>git-apply</strong>(1) for <strong>range-diff</strong>, the output is not intended to be machine-readable.</p><p>This is particularly true when passing in diff options. Currently some options like <strong>--stat</strong> can, as an emergent effect, produce output that&#39;s quite useless in the context of <strong>range-diff</strong>. Future versions of <strong>range-diff</strong> may learn to interpret such options in a manner specific to <strong>range-diff</strong> (e.g. for <strong>--stat</strong> producing human-readable output which summarizes how the diffstat changed).</p><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>This command uses the *<em>diff.color.*</em> * and <strong>pager.range-diff</strong> settings (the latter is on by default). See <strong>git-config</strong>(1).</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>When a rebase required merge conflicts to be resolved, compare the changes introduced by the rebase directly afterwards using:</p><blockquote><pre><code>$ git range-diff @{u} @{1} @
</code></pre></blockquote><p>A typical output of <strong>git range-diff</strong> would look like this:</p><blockquote><pre><code>-:  ------- &gt; 1:  0ddba11 Prepare for the inevitable!
1:  c0debee = 2:  cab005e Add a helpful message at the start
2:  f00dbal ! 3:  decafe1 Describe a bug
    @@ -1,3 +1,3 @@
     Author: A U Thor &lt;author@example.com&gt;

    -TODO: Describe a bug
    +Describe a bug
    @@ -324,5 +324,6
      This is expected.

    -+What is unexpected is that it will also crash.
    ++Unexpectedly, it also crashes. This is a bug, and the jury is
    ++still out there how to fix it best. See ticket #314 for details.

      Contact
3:  bedead &lt; -:  ------- TO-UNDO
</code></pre></blockquote><p>In this example, there are 3 old and 3 new commits, where the developer removed the 3rd, added a new one before the first two, and modified the commit message of the 2nd commit as well its diff.</p><p>When the output goes to a terminal, it is color-coded by default, just like regular <strong>git diff</strong>&#39;s output. In addition, the first line (adding a commit) is green, the last line (deleting a commit) is red, the second line (with a perfect match) is yellow like the commit header of <strong>git show</strong>&#39;s output, and the third line colors the old commit red, the new one green and the rest like <strong>git show</strong>&#39;s commit header.</p><p>A naive color-coded diff of diffs is actually a bit hard to read, though, as it colors the entire lines red or green. The line that added &quot;What is unexpected&quot; in the old commit, for example, is completely red, even if the intent of the old commit was to add something.</p><p>To help with that, <strong>range</strong> uses the <strong>--dual-color</strong> mode by default. In this mode, the diff of diffs will retain the original diff colors, and prefix the lines with -/+ markers that have their <strong>background</strong> red or green, to make it more obvious that they describe how the diff itself changed.</p><h2 id="algorithm" tabindex="-1">ALGORITHM <a class="header-anchor" href="#algorithm" aria-label="Permalink to &quot;ALGORITHM&quot;">​</a></h2><p>The general idea is this: we generate a cost matrix between the commits in both commit ranges, then solve the least-cost assignment.</p><p>The cost matrix is populated thusly: for each pair of commits, both diffs are generated and the &quot;diff of diffs&quot; is generated, with 3 context lines, then the number of lines in that diff is used as cost.</p><p>To avoid false positives (e.g. when a patch has been removed, and an unrelated patch has been added between two iterations of the same patch series), the cost matrix is extended to allow for that, by adding fixed-cost entries for wholesale deletes/adds.</p><p>Example: Let commits <strong>1--2</strong> be the first iteration of a patch series and <strong>A--C</strong> the second iteration. Let&#39;s assume that <strong>A</strong> is a cherry-pick of <strong>2,</strong> and <strong>C</strong> is a cherry-pick of <strong>1</strong> but with a small modification (say, a fixed typo). Visualize the commits as a bipartite graph:</p><blockquote><pre><code>    1            A

    2            B

                 C
</code></pre></blockquote><p>We are looking for a &quot;best&quot; explanation of the new series in terms of the old one. We can represent an &quot;explanation&quot; as an edge in the graph:</p><blockquote><pre><code>    1            A
               /
    2 --------&#39;  B

                 C
</code></pre></blockquote><p>This explanation comes for &quot;free&quot; because there was no change. Similarly <strong>C</strong> could be explained using <strong>1</strong>, but that comes at some cost c&gt;0 because of the modification:</p><blockquote><pre><code>    1 ----.      A
          |    /
    2 ----+---&#39;  B
          |
          \`----- C
          c&gt;0
</code></pre></blockquote><p>In mathematical terms, what we are looking for is some sort of a minimum cost bipartite matching; <strong>1</strong> is matched to <strong>C</strong> at some cost, etc. The underlying graph is in fact a complete bipartite graph; the cost we associate with every edge is the size of the diff between the two commits&#39; patches. To explain also new commits, we introduce dummy nodes on both sides:</p><blockquote><pre><code>    1 ----.      A
          |    /
    2 ----+---&#39;  B
          |
    o     \`----- C
          c&gt;0
    o            o

    o            o
</code></pre></blockquote><p>The cost of an edge <strong>o--C</strong> is the size of <strong>C</strong>&#39;s diff, modified by a fudge factor that should be smaller than 100%. The cost of an edge <strong>o--o</strong> is free. The fudge factor is necessary because even if <strong>1</strong> and <strong>C</strong> have nothing in common, they may still share a few empty lines and such, possibly making the assignment <strong>1--C</strong>, <strong>o--o</strong> slightly cheaper than <strong>1--o</strong>, <strong>o--C</strong> even if <strong>1</strong> and <strong>C</strong> have nothing in common. With the fudge factor we require a much larger common part to consider patches as corresponding.</p><p>The overall time needed to compute this algorithm is the time needed to compute n+m commit diffs and then n*m diffs of patches, plus the time needed to compute the least-cost assignment between n and m diffs. Git uses an implementation of the Jonker-Volgenant algorithm to solve the assignment problem, which has cubic runtime complexity. The matching found in this case will look like this:</p><blockquote><pre><code>    1 ----.      A
          |    /
    2 ----+---&#39;  B
       .--+-----&#39;
    o -&#39;  \`----- C
          c&gt;0
    o ---------- o

    o ---------- o
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-log</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,64);function l(t,d,p,c,m,f){return s(),o("div",null,[n("h1",g,i(t.$params.man),1),h])}const b=e(r,[["render",l]]);export{k as __pageData,b as default};
